/* Pharmacology Lecture 17: 90 original uploaded GI/hepatobiliary MCQs. Answer keys unaltered. Clinical review flags are non-destructive. */
(function(){'use strict';const bank=[{"id":"pharm-e2-user-gastrointestinal17-mcq-001","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #1","q":"Which of the following is NOT a primary rationale for administering antiemetic medications to a vomiting patient?","options":["Preventing aspiration","Correcting dehydration and electrolyte imbalances","Increasing gastrointestinal motility in all patients","Reducing patient distress"],"answer":2,"why":"Uploaded answer key: Increasing gastrointestinal motility in all patients","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":1},{"id":"pharm-e2-user-gastrointestinal17-mcq-002","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #2","q":"Which brainstem region coordinates the complex motor pattern of emesis?","options":["Medullary vomiting center / central pattern generator receiving input from the area postrema (CTZ) and other pathways","Cerebellar cortex","Hypothalamic thermoregulatory center","Hippocampus"],"answer":0,"why":"The medullary emetic network coordinates vomiting, receiving input from the area postrema/CTZ, vestibular nuclei, vagal afferents and higher CNS areas. The CTZ detects emetogenic bloodborne signals but is not itself the entire motor coordination center.","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":2,"reviewFlag":"Lecture-specific clinical, safety, approval, or prescribing claim. Preserve the source key for study; independently verify before clinical use.","originalImportedQuestion":"Which region of the central nervous system is identified in the lecture as the primary regulator of emesis?","originalImportedAnswer":"Chemoreceptor trigger zone (CTZ)","originalImportedWhy":"Uploaded answer key: Chemoreceptor trigger zone (CTZ)"},{"id":"pharm-e2-user-gastrointestinal17-mcq-003","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #3","q":"Which combination correctly identifies the five endogenous agonists involved in CTZ activation?","options":["Norepinephrine, dopamine, GABA, glutamate, and glycine","Serotonin, cortisol, insulin, glucagon, and histamine","Acetylcholine, norepinephrine, histamine, epinephrine, and Substance P","Serotonin, histamine, acetylcholine, dopamine, and Substance P"],"answer":3,"why":"Uploaded answer key: Serotonin, histamine, acetylcholine, dopamine, and Substance P","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":3},{"id":"pharm-e2-user-gastrointestinal17-mcq-004","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #4","q":"Why are D2, 5-HT3 and NK1 receptors useful antiemetic drug targets?","options":["They are exclusively expressed in the gastrointestinal tract.","Their antagonism can suppress emesis while avoiding many widespread effects associated with muscarinic and H1 antagonism.","They directly stimulate gastric acid secretion.","They prevent all gastrointestinal bacterial infections."],"answer":1,"why":"Emesis is coordinated by several overlapping afferent pathways. Blocking D2, 5-HT3 or NK1 signaling can interrupt important triggers without relying on broader histamine or muscarinic antagonism, although every antiemetic has its own risks.","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":4,"reviewFlag":"Lecture-specific clinical, safety, approval, or prescribing claim. Preserve the source key for study; independently verify before clinical use.","originalImportedWhy":"Uploaded answer key: Their antagonism can suppress emesis while avoiding many widespread effects associated with muscarinic and H1 antagonism.","rationaleStatus":"reviewed-mechanism","originalImportedQuestion":"hy are 5-HT3, D2, and NK1 receptors preferred targets for antiemetic therapy?","originalImportedAnswer":"Their antagonism can suppress emesis while avoiding many widespread effects associated with muscarinic and H1 antagonism."},{"id":"pharm-e2-user-gastrointestinal17-mcq-005","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #5","q":"Which antiemetic is a dopamine D2 receptor antagonist?","options":["Maropitant","Ondansetron","Metoclopramide","Ropinirole"],"answer":2,"why":"Metoclopramide antagonizes dopamine D2 receptors at emetic sites and has gastrointestinal prokinetic actions, helping gastric emptying in appropriate patients. It can produce behavioral excitation and should be avoided with mechanical obstruction.","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":5,"originalImportedQuestion":"Which antiemetic is a dopamine D2 receptor antagonist?","originalImportedAnswer":"Metoclopramide","originalImportedWhy":"Uploaded answer key: Metoclopramide"},{"id":"pharm-e2-user-gastrointestinal17-mcq-006","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #6","q":"Which antiemetic is particularly effective in dogs when administered as a constant-rate infusion (CRI)?","options":["Metoclopramide","Maropitant","Ondansetron","Apomorphine"],"answer":0,"why":"Uploaded answer key: Metoclopramide","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":6},{"id":"pharm-e2-user-gastrointestinal17-mcq-007","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #7","q":"Which additional therapeutic effect distinguishes metoclopramide from the other two primary antiemetics?","options":["Direct inhibition of gastric acid production","Prevention of intestinal bacterial growth","Inhibition of pancreatic enzyme secretion","Stimulation of gastric emptying"],"answer":3,"why":"Uploaded answer key: Stimulation of gastric emptying","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":7},{"id":"pharm-e2-user-gastrointestinal17-mcq-008","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #8","q":"A dog has chemotherapy-associated vomiting. Which antiemetic strategy is generally more directly targeted than assuming metoclopramide is always preferred?","options":["Ropinirole (D2 agonist), to trigger more emesis","A 5-HT3 antagonist such as ondansetron, or an NK1 antagonist such as maropitant, chosen for the patient","Famotidine as the sole antiemetic","Cisapride to induce gastric contractions"],"answer":1,"why":"Chemotherapy-associated emesis often involves serotonin-mediated signaling, supporting 5-HT3 antagonists; NK1 antagonists also target central emetic pathways. Metoclopramide is a D2 antagonist/prokinetic, but it is not universally the preferred antiemetic for chemotherapy patients.","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":8,"reviewFlag":"Lecture-specific clinical, safety, approval, or prescribing claim. Preserve the source key for study; independently verify before clinical use.","originalImportedQuestion":"A dog undergoing chemotherapy develops significant vomiting. According to the lecture, which antiemetic is preferred?","originalImportedAnswer":"Metoclopramide","originalImportedWhy":"Uploaded answer key: Metoclopramide"},{"id":"pharm-e2-user-gastrointestinal17-mcq-009","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #9","q":"Which adverse effect is particularly associated with metoclopramide?","options":["Severe hypoglycemia","Permanent blindness","Frenzied activity or behavioral excitation","Profound bradycardia"],"answer":2,"why":"Uploaded answer key: Frenzied activity or behavioral excitation","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":9},{"id":"pharm-e2-user-gastrointestinal17-mcq-010","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #10","q":"A dog presents with persistent vomiting, and abdominal radiographs reveal a mechanical gastrointestinal obstruction. Which medication should be avoided because of its prokinetic effects?","options":["Metoclopramide","Maropitant","Ondansetron","Sucralfate"],"answer":0,"why":"Prokinetics augment contractile activity; when bowel or gastric outflow is obstructed mechanically, stronger contractions can worsen pain, distension or perforation risk. Identify and address obstruction before promoting transit.","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":10,"originalImportedQuestion":"A dog presents with persistent vomiting, and abdominal radiographs reveal a mechanical gastrointestinal obstruction. Which medication should be avoided because of its prokinetic effects?","originalImportedAnswer":"Metoclopramide","originalImportedWhy":"Uploaded answer key: Metoclopramide"},{"id":"pharm-e2-user-gastrointestinal17-mcq-011","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #11","q":"What is the mechanism of action of maropitant?","options":["D2 receptor agonism","5-HT4 receptor antagonism","H2 receptor antagonism","NK1 receptor antagonism"],"answer":3,"why":"Maropitant is an NK1 receptor antagonist that blocks substance P signaling in central emetic pathways, suppressing vomiting from multiple stimuli without necessarily resolving the underlying illness.","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":11,"originalImportedQuestion":"What is the mechanism of action of maropitant?","originalImportedAnswer":"NK1 receptor antagonism","originalImportedWhy":"Uploaded answer key: NK1 receptor antagonism"},{"id":"pharm-e2-user-gastrointestinal17-mcq-012","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #12","q":"Which combination of inputs does maropitant suppress according to the lecture?","options":["Gastric acid secretion and pancreatic enzyme release","Visceral afferent and vestibular inputs involved in emesis","Insulin secretion and glucagon release","Enteric acetylcholine release and intestinal peristalsis"],"answer":1,"why":"NK1 blockade interrupts substance P transmission in central emetic pathways receiving vagal and vestibular signals. This broad action helps when the trigger is not exclusively dopamine- or serotonin-mediated.","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":12,"originalImportedWhy":"Uploaded answer key: Visceral afferent and vestibular inputs involved in emesis","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-gastrointestinal17-mcq-013","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #13","q":"Which statement regarding maropitant administration is correct?","options":["It is administered exclusively orally.","It is approved only for horses.","It may be administered subcutaneously, by slow IV injection, or orally.","It must always be administered as a CRI."],"answer":2,"why":"Uploaded answer key: It may be administered subcutaneously, by slow IV injection, or orally.","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":13},{"id":"pharm-e2-user-gastrointestinal17-mcq-014","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #14","q":"Which patient requires particular caution when receiving maropitant?","options":["A dog with significant hepatic dysfunction","A healthy dog with motion sickness","A cat with uncomplicated vomiting","A dog receiving routine preventive care"],"answer":0,"why":"Maropitant undergoes hepatic metabolism. Significant liver dysfunction may alter exposure, so drug choice and monitoring should consider the patient's hepatic status.","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":14,"originalImportedWhy":"Uploaded answer key: A dog with significant hepatic dysfunction","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-gastrointestinal17-mcq-015","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #15","q":"Which statement best describes the adverse-effect profile of maropitant?","options":["Severe adverse effects occur in nearly all patients.","It consistently causes frenzied activity.","It causes irreversible renal failure.","Adverse effects are uncommon."],"answer":3,"why":"Uploaded answer key: Adverse effects are uncommon.","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":15},{"id":"pharm-e2-user-gastrointestinal17-mcq-016","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #16","q":"What is the mechanism of action of ondansetron?","options":["NK1 receptor agonism","5-HT3 serotonin receptor antagonism","D2 receptor agonism","Muscarinic receptor stimulation"],"answer":1,"why":"Ondansetron blocks serotonin 5-HT3 receptors on vagal afferents and in emetic pathways. It can help chemotherapy-related and refractory nausea/vomiting; dose and patient selection remain important.","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":16,"reviewFlag":"Lecture-specific clinical, safety, approval, or prescribing claim. Preserve the source key for study; independently verify before clinical use.","originalImportedQuestion":"What is the mechanism of action of ondansetron?","originalImportedAnswer":"5-HT3 serotonin receptor antagonism","originalImportedWhy":"Uploaded answer key: 5-HT3 serotonin receptor antagonism"},{"id":"pharm-e2-user-gastrointestinal17-mcq-017","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #17","q":"Which statement best describes ondansetron's clinical role according to the lecture?","options":["It is used exclusively to induce vomiting.","It is contraindicated in all cancer patients.","It is reserved for severe or refractory emesis and is useful for cancer-associated vomiting.","It primarily stimulates gastrointestinal motility."],"answer":2,"why":"Uploaded answer key: It is reserved for severe or refractory emesis and is useful for cancer-associated vomiting.","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":17},{"id":"pharm-e2-user-gastrointestinal17-mcq-018","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #18","q":"A dog continues vomiting despite appropriately dosed metoclopramide and maropitant. What is the next recommended pharmacologic step?","options":["Try ondansetron.","Administer ropinirole.","Begin oral erythromycin.","Discontinue all supportive care."],"answer":0,"why":"Persistent emesis despite one pathway's blockade may respond to another target such as 5-HT3 receptors. At the same time, re-evaluate dehydration, obstruction, systemic disease and the reason for treatment failure.","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":18,"reviewFlag":"Lecture-specific clinical, safety, approval, or prescribing claim. Preserve the source key for study; independently verify before clinical use.","originalImportedWhy":"Uploaded answer key: Try ondansetron.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-gastrointestinal17-mcq-019","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #19","q":"A cat continues vomiting despite treatment with ondansetron. What should the veterinarian consider according to the lecture?","options":["The vomiting must be caused by a dietary indiscretion.","The cat requires a higher dose of a pro-emetic.","The patient has no underlying disease.","A more serious extra-gastrointestinal disease may be present."],"answer":3,"why":"Persistent vomiting despite appropriate antiemetic treatment should trigger reassessment for obstruction, renal or hepatic disease, pancreatitis, toxicosis and other systemic causes. Symptom control alone does not establish diagnosis.","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":19,"reviewFlag":"Lecture-specific clinical, safety, approval, or prescribing claim. Preserve the source key for study; independently verify before clinical use.","originalImportedWhy":"Uploaded answer key: A more serious extra-gastrointestinal disease may be present.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-gastrointestinal17-mcq-020","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #20","q":"Which drug is approved as an ophthalmic emetic in dogs?","options":["Apomorphine","Ropinirole","Hydromorphone","Xylazine"],"answer":1,"why":"Uploaded answer key: Ropinirole","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":20},{"id":"pharm-e2-user-gastrointestinal17-mcq-021","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #21","q":"How does ropinirole induce vomiting?","options":["By irritating the gastric mucosa","By antagonizing NK1 receptors","By stimulating dopamine D2 receptors","By inhibiting serotonin release"],"answer":2,"why":"Ropinirole activates dopamine D2 receptors in canine emetic signaling pathways. This is a deliberately opposite action to D2-blocking metoclopramide.","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":21,"originalImportedWhy":"Uploaded answer key: By stimulating dopamine D2 receptors","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-gastrointestinal17-mcq-022","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #22","q":"Following successful ropinirole-induced vomiting in a dog, which medication can be administered to reverse the emetic effect?","options":["Metoclopramide","Apomorphine","Hydromorphone","Neostigmine"],"answer":0,"why":"Metoclopramide antagonizes dopamine D2 receptors that ropinirole stimulated, helping turn off the central emetic response when appropriate.","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":22,"reviewFlag":"Lecture-specific clinical, safety, approval, or prescribing claim. Preserve the source key for study; independently verify before clinical use.","originalImportedWhy":"Uploaded answer key: Metoclopramide","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-gastrointestinal17-mcq-023","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #23","q":"Which statement best describes apomorphine as a canine emetic?","options":["It is an NK1 receptor antagonist.","It is an H2 receptor blocker.","It is the preferred emetic in cats.","It is a dopamine receptor agonist used to induce emesis in dogs; formulation and availability vary."],"answer":3,"why":"Apomorphine activates central dopamine receptors in the chemoreceptor trigger zone, producing vomiting in dogs. The requirement for compounding is formulation-dependent and not an inherent pharmacologic property.","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":23,"originalImportedQuestion":"Which statement regarding apomorphine is correct?","originalImportedAnswer":"It is a dopamine D2 receptor agonist that the lecture states requires compounding.","originalImportedWhy":"Uploaded answer key: It is a dopamine D2 receptor agonist that the lecture states requires compounding."},{"id":"pharm-e2-user-gastrointestinal17-mcq-024","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #24","q":"What is the mechanism by which hydrogen peroxide induces vomiting?","options":["Dopamine receptor activation","Gastric irritation","Serotonin receptor inhibition","Increased intestinal acetylcholine release"],"answer":1,"why":"Hydrogen peroxide irritates gastric mucosa and can trigger emesis through local injury and vagal signaling. Because irritation can be severe, its use is not a routine substitute for veterinary-directed decontamination.","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":24,"reviewFlag":"Lecture-specific clinical, safety, approval, or prescribing claim. Preserve the source key for study; independently verify before clinical use.","originalImportedWhy":"Uploaded answer key: Gastric irritation","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-gastrointestinal17-mcq-025","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #25","q":"Why should induction of vomiting at home with hydrogen peroxide not be a routine recommendation?","options":["Concentrated hydrogen peroxide is safer than diluted products.","Hydrogen peroxide has no potential for mucosal injury.","It may cause severe gastritis, esophageal irritation or aspiration; contact a veterinarian or poison service for case-specific advice.","It is approved for inducing emesis in horses."],"answer":2,"why":"Hydrogen peroxide irritates gastric mucosa and can cause injury and aspiration, especially if emesis is unsuccessful or the exposure is contraindicated. A 3% concentration is not automatically safe or appropriate for every dog; avoid its use in cats.","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":25,"originalImportedQuestion":"Which statement about hydrogen peroxide is emphasized in the lecture?","originalImportedAnswer":"Only fresh 3% hydrogen peroxide without additional cleaning agents should be considered.","originalImportedWhy":"Uploaded answer key: Only fresh 3% hydrogen peroxide without additional cleaning agents should be considered."},{"id":"pharm-e2-user-gastrointestinal17-mcq-026","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #26","q":"Which two medications are identified as pro-emetics in cats?","options":["Hydromorphone and low-dose xylazine","Ropinirole and ondansetron","Maropitant and metoclopramide","Cisapride and erythromycin"],"answer":0,"why":"Uploaded answer key: Hydromorphone and low-dose xylazine","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":26,"reviewFlag":"Lecture-specific clinical, safety, approval, or prescribing claim. Preserve the source key for study; independently verify before clinical use."},{"id":"pharm-e2-user-gastrointestinal17-mcq-027","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #27","q":"Why are pro-emetic medications not used in horses?","options":["Horses lack dopamine receptors.","Horses have no gastrointestinal tract.","Horses metabolize emetics too rapidly.","Horses cannot vomit under normal physiologic circumstances."],"answer":3,"why":"The equine gastroesophageal junction, esophageal entry angle and associated structures strongly resist retrograde emptying. This is why induced vomiting is not a standard equine decontamination procedure.","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":27,"originalImportedWhy":"Uploaded answer key: Horses cannot vomit under normal physiologic circumstances.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-gastrointestinal17-mcq-028","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #28","q":"Which condition is an appropriate indication for a gastrointestinal prokinetic medication?","options":["Complete mechanical intestinal obstruction","Non-obstructive ileus","Intestinal perforation","Gastric volvulus"],"answer":1,"why":"Uploaded answer key: Non-obstructive ileus","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":28,"reviewFlag":"Lecture-specific clinical, safety, approval, or prescribing claim. Preserve the source key for study; independently verify before clinical use."},{"id":"pharm-e2-user-gastrointestinal17-mcq-029","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #29","q":"A dog undergoes gastroscopy after fasting, and the stomach contains substantial retained ingesta. Which underlying dysfunction should be suspected?","options":["Excessive gastric acid production","Increased intestinal secretion","Gastric hypomotility or delayed emptying","Increased gastric peristalsis"],"answer":2,"why":"Retained gastric ingesta after adequate fasting suggests impaired emptying, but obstruction and patient preparation must be assessed. Prokinetics are inappropriate until mechanical obstruction is excluded.","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":29,"originalImportedWhy":"Uploaded answer key: Gastric hypomotility or delayed emptying","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-gastrointestinal17-mcq-030","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #30","q":"A gastroscopy image demonstrates substantial retained gastric fluid despite an appropriate fasting period. Which condition is most consistent with this finding?","options":["Gastroparesis","Hyperthyroidism","Increased gastric motility","Exocrine pancreatic insufficiency"],"answer":0,"why":"Uploaded answer key: Gastroparesis","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":30},{"id":"pharm-e2-user-gastrointestinal17-mcq-031","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #31","q":"What is the mechanism of action of cisapride?","options":["D2 receptor antagonism","NK1 receptor antagonism","H2 receptor agonism","5-HT4 receptor agonism"],"answer":3,"why":"Cisapride stimulates enteric 5-HT4 receptors, promoting acetylcholine release and gastrointestinal propulsive contractions. Its QT-prolongation interaction risk makes medication review important.","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":31,"originalImportedQuestion":"What is the mechanism of action of cisapride?","originalImportedAnswer":"5-HT4 receptor agonism","originalImportedWhy":"Uploaded answer key: 5-HT4 receptor agonism"},{"id":"pharm-e2-user-gastrointestinal17-mcq-032","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #32","q":"How does cisapride enhance gastrointestinal motility?","options":["By decreasing acetylcholine release","By increasing enteric acetylcholine release","By inhibiting intestinal smooth muscle contraction","By stimulating aldosterone receptors"],"answer":1,"why":"5-HT4 receptors on enteric neurons facilitate acetylcholine release, strengthening coordinated gastrointestinal smooth-muscle contractions. This differs from directly stimulating muscarinic receptors on muscle.","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":32,"originalImportedWhy":"Uploaded answer key: By increasing enteric acetylcholine release","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-gastrointestinal17-mcq-033","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #33","q":"Why was the human formulation of cisapride removed from the marketplace?","options":["Severe nephrotoxicity","Irreversible blindness","Cardiotoxicity associated with QT prolongation","Excessive gastric acid production"],"answer":2,"why":"Cisapride can inhibit cardiac repolarization currents and prolong QT, potentially triggering ventricular arrhythmias. Review interactions with other QT-prolonging or metabolism-inhibiting drugs.","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":33,"originalImportedWhy":"Uploaded answer key: Cardiotoxicity associated with QT prolongation","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-gastrointestinal17-mcq-034","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #34","q":"Which statement best describes cisapride's gastrointestinal effects?","options":["It is highly effective and acts throughout the gastrointestinal tract.","It acts only in the stomach.","It acts exclusively in the colon.","It is ineffective in veterinary patients."],"answer":0,"why":"Uploaded answer key: It is highly effective and acts throughout the gastrointestinal tract.","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":34,"reviewFlag":"Lecture-specific clinical, safety, approval, or prescribing claim. Preserve the source key for study; independently verify before clinical use."},{"id":"pharm-e2-user-gastrointestinal17-mcq-035","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #35","q":"Which H2 receptor antagonists also possess prokinetic activity?","options":["Famotidine and cimetidine","Omeprazole and pantoprazole","Maropitant and ondansetron","Ranitidine and nizatidine"],"answer":3,"why":"Uploaded answer key: Ranitidine and nizatidine","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":35},{"id":"pharm-e2-user-gastrointestinal17-mcq-036","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #36","q":"How do ranitidine and nizatidine enhance gastrointestinal motility?","options":["By inhibiting serotonin receptors","By inhibiting acetylcholinesterase, increasing acetylcholine availability","By stimulating NK1 receptors","By directly inhibiting gastric proton pumps"],"answer":1,"why":"Some older H2 antagonists have additional cholinesterase-inhibiting activity, allowing more acetylcholine to reach enteric muscarinic targets. Not all H2 blockers share that prokinetic action.","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":36,"originalImportedWhy":"Uploaded answer key: By inhibiting acetylcholinesterase, increasing acetylcholine availability","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-gastrointestinal17-mcq-037","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #37","q":"Why are famotidine and cimetidine not included among the H2 antagonists used for prokinetic effects?","options":["They irreversibly inhibit acetylcholinesterase.","They stimulate intestinal dopamine receptors.","They lack the relevant anticholinesterase activity emphasized for ranitidine and nizatidine.","They are exclusively injectable medications."],"answer":2,"why":"Famotidine and cimetidine reduce histamine-dependent acid secretion without the meaningful cholinesterase inhibition described for ranitidine/nizatidine; being in the same acid-suppressant class does not guarantee identical motility effects.","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":37,"originalImportedWhy":"Uploaded answer key: They lack the relevant anticholinesterase activity emphasized for ranitidine and nizatidine.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-gastrointestinal17-mcq-038","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #38","q":"At sub-antimicrobial concentrations, erythromycin enhances gastrointestinal motility through which mechanism?","options":["Motilin receptor agonism","NK1 receptor antagonism","Dopamine receptor stimulation","Histamine receptor activation"],"answer":0,"why":"Uploaded answer key: Motilin receptor agonism","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":38},{"id":"pharm-e2-user-gastrointestinal17-mcq-039","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #39","q":"Why are lower doses of erythromycin sufficient for its prokinetic effects?","options":["Its antibacterial activity directly increases peristalsis.","It permanently blocks intestinal sodium channels.","It requires bacterial killing to stimulate motility.","Motilin receptor activation generally occurs at doses below those required for antibacterial effects."],"answer":3,"why":"Motilin receptors influence upper-GI motor patterns and respond to low erythromycin exposures. The prokinetic effect is separate from bacterial ribosome inhibition at antimicrobial doses.","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":39,"originalImportedWhy":"Uploaded answer key: Motilin receptor activation generally occurs at doses below those required for antibacterial effects.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-gastrointestinal17-mcq-040","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #40","q":"Why are prokinetic medications contraindicated in gastrointestinal obstruction?","options":["They completely inhibit gastric secretion.","Increasing motility against a mechanical obstruction can worsen the condition.","They prevent intestinal blood flow in every patient.","They irreversibly suppress intestinal smooth muscle contraction."],"answer":1,"why":"Increasing contraction against a blocked intestinal segment can increase distension, pressure and tissue damage. Radiographic or other evaluation for mechanical obstruction matters before a motility stimulant.","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":40,"originalImportedWhy":"Uploaded answer key: Increasing motility against a mechanical obstruction can worsen the condition.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-gastrointestinal17-mcq-041","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #41","q":"Why might a lidocaine CRI be considered for selected horses with postoperative ileus?","options":["Its neuronal and possible anti-inflammatory effects may support motility, although the complete clinical mechanism is not established.","It exclusively blocks sympathetic nerves and directly activates muscarinic receptors.","It irreversibly stimulates H2 receptors.","It causes a mechanical intestinal obstruction to resolve."],"answer":0,"why":"IV lidocaine has been evaluated for selected equine postoperative ileus, with neuronal and potentially anti-inflammatory actions. The original claim that it exclusively blocks sympathetic sodium channels to favor parasympathetic activity overstated a proposed mechanism.","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":41,"originalImportedWhy":"Uploaded answer key: By inhibiting sympathetic voltage-gated sodium channels, favoring parasympathetic activity","rationaleStatus":"reviewed-mechanism","originalImportedQuestion":"According to the lecture, how does a lidocaine CRI enhance gastrointestinal motility in horses?","originalImportedAnswer":"By inhibiting sympathetic voltage-gated sodium channels, favoring parasympathetic activity","reviewFlag":"Replaced the oversimplified mechanistic explanation for equine lidocaine CRI."},{"id":"pharm-e2-user-gastrointestinal17-mcq-042","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #42","q":"Which statement correctly distinguishes bethanechol from neostigmine?","options":["Bethanechol is a muscarinic receptor agonist, while neostigmine inhibits acetylcholinesterase.","Bethanechol inhibits NK1 receptors, while neostigmine stimulates dopamine receptors.","Both medications inhibit muscarinic receptors.","Bethanechol is an H2 blocker, while neostigmine is a proton pump inhibitor."],"answer":0,"why":"Uploaded answer key: Bethanechol is a muscarinic receptor agonist, while neostigmine inhibits acetylcholinesterase.","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":42,"reviewFlag":"Lecture-specific clinical, safety, approval, or prescribing claim. Preserve the source key for study; independently verify before clinical use."},{"id":"pharm-e2-user-gastrointestinal17-mcq-043","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #43","q":"Which medication acts as an osmotic agent for treating fecal impactions in horses?","options":["Mineral oil","Psyllium","Buscopan","Magnesium sulfate"],"answer":3,"why":"Uploaded answer key: Magnesium sulfate","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":43},{"id":"pharm-e2-user-gastrointestinal17-mcq-044","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #44","q":"What duration limitation is emphasized for magnesium sulfate administration in horses?","options":["It must never be used more than once.","It should not be administered for more than three consecutive days because toxicity may develop.","It is safe for indefinite daily administration.","It should only be administered for 30 days."],"answer":1,"why":"Magnesium sulfate retains water osmotically in bowel contents; overuse may cause fluid/electrolyte disturbances and magnesium accumulation. Duration limits from a lecture are not a universal prescription.","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":44,"originalImportedWhy":"Uploaded answer key: It should not be administered for more than three consecutive days because toxicity may develop.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-gastrointestinal17-mcq-045","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #45","q":"Which statement best describes mineral oil's therapeutic mechanism in equine colic?","options":["It stimulates motilin receptors.","It directly inhibits muscarinic receptors.","It lubricates intestinal contents and reduces water reabsorption.","It stimulates pancreatic enzyme release."],"answer":2,"why":"Mineral oil acts largely as a lubricant within the lumen. It does not mechanically remove an obstruction and must be administered by an appropriate route because aspiration can cause severe lipoid pneumonia.","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":45,"originalImportedWhy":"Uploaded answer key: It lubricates intestinal contents and reduces water reabsorption.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-gastrointestinal17-mcq-046","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #46","q":"In a horse receiving nasogastric mineral oil for suspected impaction, which interpretation of absent oil in feces is most appropriate?","options":["Delayed transit or obstruction is possible but absence alone is not diagnostic; reassess clinical signs and gastrointestinal transit.","Excessive intestinal motility is confirmed.","Increased gastric acid production is established.","Normal transit is proven."],"answer":0,"why":"Mineral oil may be used as a marker, but transit times vary with ileus, impaction and hydration. A single absent observation cannot definitively diagnose mechanical obstruction, which requires clinical assessment.","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":46,"originalImportedQuestion":"Mineral oil is administered to a horse as a gastrointestinal transit marker. What does failure to detect mineral oil in the feces suggest according to the lecture?","originalImportedAnswer":"Gastrointestinal obstruction","originalImportedWhy":"Uploaded answer key: Gastrointestinal obstruction"},{"id":"pharm-e2-user-gastrointestinal17-mcq-047","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #47","q":"Which treatment is primarily indicated for sand impaction in horses?","options":["Magnesium sulfate","Metoclopramide","Ranitidine","Psyllium husk"],"answer":3,"why":"Uploaded answer key: Psyllium husk","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":47,"reviewFlag":"Lecture-specific clinical, safety, approval, or prescribing claim. Preserve the source key for study; independently verify before clinical use."},{"id":"pharm-e2-user-gastrointestinal17-mcq-048","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #48","q":"What is the mechanism of action of butylscopolammonium bromide (Buscopan)?","options":["Motilin receptor agonism","Muscarinic receptor antagonism","Dopamine D2 receptor antagonism","Serotonin 5-HT4 receptor agonism"],"answer":1,"why":"Uploaded answer key: Muscarinic receptor antagonism","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":48,"reviewFlag":"Lecture-specific clinical, safety, approval, or prescribing claim. Preserve the source key for study; independently verify before clinical use."},{"id":"pharm-e2-user-gastrointestinal17-mcq-049","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #49","q":"Which form of equine colic is particularly appropriate for Buscopan therapy according to the lecture?","options":["Sand impaction exclusively","Ascarid impaction exclusively","Gaseous or spasmodic colic","Gastric ulceration exclusively"],"answer":2,"why":"Uploaded answer key: Gaseous or spasmodic colic","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":49,"reviewFlag":"Lecture-specific clinical, safety, approval, or prescribing claim. Preserve the source key for study; independently verify before clinical use."},{"id":"pharm-e2-user-gastrointestinal17-mcq-050","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #50","q":"What is the primary clinical purpose of butylscopolammonium (Buscopan) in horses?","options":["To stimulate stomach acid production.","To treat the infectious cause of equine protozoal myeloencephalitis.","To provide short-lived antispasmodic relief of selected gastrointestinal smooth-muscle spasm.","To reverse a complete mechanical esophageal obstruction."],"answer":2,"why":"Buscopan is a quaternary antimuscarinic that relaxes smooth muscle, providing temporary relief of selected spasmodic colic. It does not clear choke mechanically or definitively resolve obstructive colic.","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":50,"originalImportedQuestion":"Which additional equine condition may be addressed with Buscopan?","originalImportedAnswer":"Choke","originalImportedWhy":"Uploaded answer key: Choke","reviewFlag":"Removed unsupported indication claiming Buscopan definitively treats choke."},{"id":"pharm-e2-user-gastrointestinal17-mcq-051","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #51","q":"What distinguishes a gastrointestinal ulcer from an erosion?","options":["Erosions extend into the muscularis, while ulcers remain superficial.","Ulcers only involve the epithelial surface.","Erosions always cause perforation.","Ulcers involve deeper mucosal disruption, potentially extending into the submucosa or muscularis."],"answer":3,"why":"Uploaded answer key: Ulcers involve deeper mucosal disruption, potentially extending into the submucosa or muscularis.","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":51},{"id":"pharm-e2-user-gastrointestinal17-mcq-052","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #52","q":"Which three endogenous substances promote gastric hydrochloric acid secretion?","options":["Prostaglandin E1, prostaglandin E2, and serotonin","Gastrin, acetylcholine, and histamine","Dopamine, Substance P, and motilin","Glucagon, insulin, and somatostatin"],"answer":1,"why":"Uploaded answer key: Gastrin, acetylcholine, and histamine","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":52},{"id":"pharm-e2-user-gastrointestinal17-mcq-053","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #53","q":"What are the major protective actions of PGE1 and PGE2 in the stomach?","options":["Increased acid secretion and reduced mucus production","Increased pepsin release and reduced bicarbonate secretion","Reduced gastric acid secretion and increased mucus production","Increased gastrin release and gastric motility"],"answer":2,"why":"Gastric prostaglandins inhibit parietal-cell acid secretion and enhance mucus, bicarbonate and mucosal blood flow. Losing that protection increases susceptibility to acid injury.","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":53,"originalImportedWhy":"Uploaded answer key: Reduced gastric acid secretion and increased mucus production","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-gastrointestinal17-mcq-054","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #54","q":"Why can corticosteroids contribute to gastrointestinal ulceration according to the lecture?","options":["They inhibit phospholipase A2, reducing protective prostaglandin production.","They directly stimulate H2 receptors.","They irreversibly activate proton pumps.","They increase gastric mucus production."],"answer":0,"why":"Glucocorticoids reduce phospholipase A2-driven arachidonic-acid pathways, but the magnitude of ulcer risk is context-dependent, especially when combined with NSAIDs or critical illness. They do not invariably cause ulcers by themselves.","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":54,"originalImportedWhy":"Uploaded answer key: They inhibit phospholipase A2, reducing protective prostaglandin production.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-gastrointestinal17-mcq-055","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #55","q":"How do NSAIDs increase the risk of gastric ulcers?","options":["By stimulating prostaglandin synthesis","By directly increasing bicarbonate production","By antagonizing gastrin receptors","By inhibiting COX-1 and COX-2, reducing protective prostaglandin production"],"answer":3,"why":"Omeprazole and other proton pump inhibitors inhibit the parietal H+/K+-ATPase, suppressing the final common step in gastric acid secretion. They act differently from H2 antagonists and from direct mucosal protectants.","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":55,"originalImportedQuestion":"How do NSAIDs increase the risk of gastric ulcers?","originalImportedAnswer":"By inhibiting COX-1 and COX-2, reducing protective prostaglandin production","originalImportedWhy":"Uploaded answer key: By inhibiting COX-1 and COX-2, reducing protective prostaglandin production"},{"id":"pharm-e2-user-gastrointestinal17-mcq-056","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #56","q":"According to the lecture, which treatment hierarchy is correct for gastrointestinal ulcers?","options":["H2 blockers, misoprostol, sucralfate, PPIs","PPIs, sucralfate, PGE1 receptor agonists, H2 blockers","Sucralfate, H2 blockers, PPIs, antibiotics","Misoprostol, antibiotics, H2 blockers, PPIs"],"answer":1,"why":"Uploaded answer key: PPIs, sucralfate, PGE1 receptor agonists, H2 blockers","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":56,"reviewFlag":"Lecture-specific clinical, safety, approval, or prescribing claim. Preserve the source key for study; independently verify before clinical use."},{"id":"pharm-e2-user-gastrointestinal17-mcq-057","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #57","q":"What is the mechanism of action of proton pump inhibitors?","options":["Reversible H2 receptor antagonism","Direct neutralization of gastric acid","Irreversible inhibition of the H⁺/K⁺-ATPase proton pump","Stimulation of prostaglandin receptors"],"answer":2,"why":"Uploaded answer key: Irreversible inhibition of the H⁺/K⁺-ATPase proton pump","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":57},{"id":"pharm-e2-user-gastrointestinal17-mcq-058","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #58","q":"Which statement correctly identifies omeprazole and pantoprazole formulations emphasized in the lecture?","options":["Omeprazole is administered orally and is approved in horses; pantoprazole is administered intravenously.","Both medications are exclusively intramuscular.","Pantoprazole is an H2 receptor antagonist.","Omeprazole is a prostaglandin receptor agonist."],"answer":0,"why":"Uploaded answer key: Omeprazole is administered orally and is approved in horses; pantoprazole is administered intravenously.","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":58,"reviewFlag":"Lecture-specific clinical, safety, approval, or prescribing claim. Preserve the source key for study; independently verify before clinical use."},{"id":"pharm-e2-user-gastrointestinal17-mcq-059","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #59","q":"Which drug class is identified as the first choice for GI ulcers, especially when esophagitis is also present?","options":["H2 receptor antagonists","Prokinetic agents","Anticholinergic agents","Proton pump inhibitors"],"answer":3,"why":"Uploaded answer key: Proton pump inhibitors","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":59},{"id":"pharm-e2-user-gastrointestinal17-mcq-060","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #60","q":"What is the primary mechanism of action of sucralfate?","options":["Direct inhibition of H2 receptors","Formation of a viscous, adherent protective coating over ulcers and erosions","Stimulation of gastric acid secretion","Direct inhibition of the proton pump"],"answer":1,"why":"Sucralfate binds exposed proteins in ulcerated tissue to form a protective local barrier; it does not produce immediate acid suppression like a proton-pump inhibitor.","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":60,"originalImportedWhy":"Uploaded answer key: Formation of a viscous, adherent protective coating over ulcers and erosions","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-gastrointestinal17-mcq-061","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #61","q":"In addition to coating ulcers, what protective effect does sucralfate promote?","options":["Increased gastrin release","Increased histamine secretion","Prostaglandin release, reducing acid secretion and increasing mucus production","Increased gastric pepsin production"],"answer":2,"why":"Sucralfate can support local mucosal protection and prostaglandin-related defenses, but it primarily coats damaged tissue rather than directly inhibiting parietal proton pumps.","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":61,"reviewFlag":"Lecture-specific clinical, safety, approval, or prescribing claim. Preserve the source key for study; independently verify before clinical use.","originalImportedWhy":"Uploaded answer key: Prostaglandin release, reducing acid secretion and increasing mucus production","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-gastrointestinal17-mcq-062","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #62","q":"Why should oral sucralfate and a PPI be administered at staggered times?","options":["Sucralfate may reduce the gastrointestinal absorption of the PPI.","The medications directly destroy each other in the bloodstream.","Their combined administration causes immediate renal failure.","Sucralfate irreversibly inhibits PPI metabolism."],"answer":0,"why":"Sucralfate can adsorb other oral medications and impair their absorption; spacing administration helps reduce interaction risk. Specific timing should follow the medications and clinical plan.","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":62,"originalImportedWhy":"Uploaded answer key: Sucralfate may reduce the gastrointestinal absorption of the PPI.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-gastrointestinal17-mcq-063","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #63","q":"Which drug acts as a prostaglandin E1 receptor agonist?","options":["Famotidine","Pantoprazole","Ranitidine","Misoprostol"],"answer":3,"why":"Misoprostol is a prostaglandin E1 analog that reduces gastric acid secretion and promotes mucus and bicarbonate defense, useful particularly for NSAID-associated ulcer risk. Uterotonic effects make pregnancy a major caution.","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":63,"originalImportedQuestion":"Which drug acts as a prostaglandin E1 receptor agonist?","originalImportedAnswer":"Misoprostol","originalImportedWhy":"Uploaded answer key: Misoprostol"},{"id":"pharm-e2-user-gastrointestinal17-mcq-064","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #64","q":"Which combination correctly describes the effects of misoprostol?","options":["Increased acid secretion, reduced bicarbonate, and reduced mucus","Reduced acid secretion, increased bicarbonate secretion, and increased mucus production","Increased histamine secretion and increased pepsin production","Increased gastrin release and reduced gastric protection"],"answer":1,"why":"Uploaded answer key: Reduced acid secretion, increased bicarbonate secretion, and increased mucus production","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":64},{"id":"pharm-e2-user-gastrointestinal17-mcq-065","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #65","q":"Why is misoprostol contraindicated during pregnancy unless specifically indicated for obstetric use?","options":["It causes fetal hyperglycemia.","It inhibits fetal erythropoiesis.","As a prostaglandin E1 analog it promotes uterine contractility and cervical effects, risking abortion or premature labor.","It causes permanent maternal renal failure."],"answer":2,"why":"Misoprostol is a PGE1 analog that reduces gastric acid and supports mucosal defense but also activates prostaglandin receptors involved in uterine contraction/cervical ripening. The original explanation incorrectly singled out PGF2-alpha receptor activation as its mechanism.","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":65,"reviewFlag":"Lecture-specific clinical, safety, approval, or prescribing claim. Preserve the source key for study; independently verify before clinical use.","originalImportedQuestion":"Why is misoprostol contraindicated in pregnant animals according to the lecture?","originalImportedAnswer":"It can activate PGF2α receptors, causing luteolysis and pregnancy termination.","originalImportedWhy":"Uploaded answer key: It can activate PGF2α receptors, causing luteolysis and pregnancy termination."},{"id":"pharm-e2-user-gastrointestinal17-mcq-066","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #66","q":"Which clinical situation is a major indication for misoprostol?","options":["Prevention or treatment of NSAID-induced gastric ulceration","Treatment of mechanical GI obstruction","Induction of emesis in dogs","Treatment of bacterial gastroenteritis"],"answer":0,"why":"Misoprostol replaces some lost prostaglandin-mediated mucosal protection during NSAID exposure: less acid, more bicarbonate/mucus. It also stimulates uterine activity and is contraindicated in pregnancy unless specifically used for obstetric purposes.","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":66,"originalImportedWhy":"Uploaded answer key: Prevention or treatment of NSAID-induced gastric ulceration","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-gastrointestinal17-mcq-067","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #67","q":"Which statement correctly describes H2 receptor antagonists?","options":["They irreversibly inhibit proton pumps.","They stimulate histamine release.","They directly coat gastric ulcers.","They reversibly antagonize H2 histamine receptors."],"answer":3,"why":"Uploaded answer key: They reversibly antagonize H2 histamine receptors.","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":67,"reviewFlag":"Lecture-specific clinical, safety, approval, or prescribing claim. Preserve the source key for study; independently verify before clinical use."},{"id":"pharm-e2-user-gastrointestinal17-mcq-068","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #68","q":"Why do ranitidine and nizatidine have variable efficacy as antiulcer medications according to the lecture?","options":["They irreversibly stimulate proton pumps.","Their anticholinesterase activity increases acetylcholine, which can promote gastric acid secretion.","They directly inhibit mucus production.","They stimulate gastrin secretion through NK1 receptors."],"answer":1,"why":"Ranitidine/nizatidine may have additional cholinesterase inhibition, although H2 acid suppression and their prokinetic effects are distinct. Their variable clinical performance is not explained by a single simple opposing mechanism.","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":68,"originalImportedWhy":"Uploaded answer key: Their anticholinesterase activity increases acetylcholine, which can promote gastric acid secretion.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-gastrointestinal17-mcq-069","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #69","q":"Which statement correctly identifies important limitations of famotidine and cimetidine?","options":["Famotidine causes QT prolongation, while cimetidine causes pregnancy termination.","Famotidine increases acetylcholine release, while cimetidine is a motilin agonist.","Famotidine tolerance can develop within 48 hours, while cimetidine interferes with hepatic metabolism of other drugs.","Both drugs are irreversible proton pump inhibitors."],"answer":2,"why":"Famotidine is associated with rapid tolerance to acid suppression in some repeated-dosing settings, while cimetidine inhibits several hepatic drug-metabolizing enzymes and has important interaction potential.","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":69,"originalImportedWhy":"Uploaded answer key: Famotidine tolerance can develop within 48 hours, while cimetidine interferes with hepatic metabolism of other drugs.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-gastrointestinal17-mcq-070","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #70","q":"Which combination correctly identifies the four pathogenic mechanisms of diarrhea discussed in the lecture?","options":["Maldigestion, malabsorption, hypermotility, and hypersecretion","Hypomotility, hyposecretion, hypercalcemia, and hypertension","Increased gastric acid, decreased bile production, anemia, and dehydration","Gastric obstruction, pancreatic necrosis, hepatic fibrosis, and hypoglycemia"],"answer":0,"why":"Uploaded answer key: Maldigestion, malabsorption, hypermotility, and hypersecretion","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":70,"reviewFlag":"Lecture-specific clinical, safety, approval, or prescribing claim. Preserve the source key for study; independently verify before clinical use."},{"id":"pharm-e2-user-gastrointestinal17-mcq-071","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #71","q":"A dog has chronic diarrhea caused by exocrine pancreatic insufficiency. Which treatment addresses the underlying cause?","options":["Maropitant","Misoprostol","Ropinirole","Pancreatic enzyme supplementation"],"answer":3,"why":"Exocrine pancreatic insufficiency reduces delivery of digestive enzymes, so food is poorly broken down. Pancreatic enzyme replacement addresses the cause rather than merely slowing diarrhea.","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":71,"originalImportedWhy":"Uploaded answer key: Pancreatic enzyme supplementation","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-gastrointestinal17-mcq-072","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #72","q":"Which treatment is appropriate for diarrhea associated with intestinal lymphangiectasia according to the lecture?","options":["High-fat diet exclusively","Low-fat diet and appropriate medications","Routine emetic administration","Increased gastric acid secretion"],"answer":1,"why":"Intestinal lymphatic dysfunction impairs absorption and may lose lymph/protein into gut. Dietary fat restriction can lower lymphatic load, with individualized therapy for concurrent inflammation.","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":72,"originalImportedWhy":"Uploaded answer key: Low-fat diet and appropriate medications","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-gastrointestinal17-mcq-073","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #73","q":"A clinically stable dog presents with uncomplicated acute diarrhea without systemic illness. According to the lecture, are antibiotics indicated?","options":["Yes, in every patient","Yes, if vomiting is absent","No, antibiotics are generally unnecessary","Yes, but only with corticosteroids"],"answer":2,"why":"Most uncomplicated acute diarrheal episodes in stable dogs resolve with supportive care. Unnecessary antibiotics may disrupt microbiota and promote resistance without improving outcomes.","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":73,"reviewFlag":"Lecture-specific clinical, safety, approval, or prescribing claim. Preserve the source key for study; independently verify before clinical use.","originalImportedWhy":"Uploaded answer key: No, antibiotics are generally unnecessary","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-gastrointestinal17-mcq-074","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #74","q":"Which condition associated with parvoviral enteritis supports antibiotic administration according to the lecture?","options":["Severe neutropenia","Mild vomiting without systemic illness","Normal leukocyte counts","Uncomplicated soft stool"],"answer":0,"why":"Severe neutropenia and damaged intestinal barriers increase bacterial translocation and sepsis risk in parvoviral enteritis. Antimicrobials may be indicated for that systemic-risk context, not for the virus itself.","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":74,"reviewFlag":"Lecture-specific clinical, safety, approval, or prescribing claim. Preserve the source key for study; independently verify before clinical use.","originalImportedWhy":"Uploaded answer key: Severe neutropenia","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-gastrointestinal17-mcq-075","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #75","q":"Why should unnecessary antibiotic therapy be avoided in patients with diarrhea?","options":["It always causes complete intestinal obstruction.","It irreversibly suppresses pancreatic function.","It eliminates the need for supportive care.","It can cause intestinal dysbiosis."],"answer":3,"why":"Broad-spectrum antimicrobials disrupt normal gut organisms and can prolong dysbiosis, cause adverse effects and select for resistance. Treat confirmed/suspected bacterial disease rather than using them automatically.","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":75,"originalImportedWhy":"Uploaded answer key: It can cause intestinal dysbiosis.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-gastrointestinal17-mcq-076","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #76","q":"Which three antibiotics are identified as having anti-inflammatory activity in inflammatory bowel disease?","options":["Amoxicillin, cephalexin, and enrofloxacin","Metronidazole, tylosin, and sulfasalazine","Doxycycline, clindamycin, and gentamicin","Penicillin, ampicillin, and cefazolin"],"answer":1,"why":"Uploaded answer key: Metronidazole, tylosin, and sulfasalazine","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":76},{"id":"pharm-e2-user-gastrointestinal17-mcq-077","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #77","q":"What adjunctive approach does the lecture recommend to minimize antibiotic-associated dysbiosis?","options":["Increase gastric acid secretion.","Administer an emetic during therapy.","Include psyllium during treatment and probiotics after antibiotic therapy.","Eliminate all dietary fiber permanently."],"answer":2,"why":"Fiber may alter stool consistency and microbial fermentation, while probiotics have product-specific evidence. These measures do not guarantee prevention of antibiotic-associated dysbiosis.","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":77,"originalImportedWhy":"Uploaded answer key: Include psyllium during treatment and probiotics after antibiotic therapy.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-gastrointestinal17-mcq-078","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #78","q":"Which statement correctly describes bismuth salicylate?","options":["It can address secretory diarrhea, contains a COX-inhibiting salicylate, and should not be used in cats.","It is an NK1 receptor antagonist approved for cats.","It is a motilin receptor agonist.","It is a proton pump inhibitor."],"answer":0,"why":"Uploaded answer key: It can address secretory diarrhea, contains a COX-inhibiting salicylate, and should not be used in cats.","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":78,"reviewFlag":"Lecture-specific clinical, safety, approval, or prescribing claim. Preserve the source key for study; independently verify before clinical use."},{"id":"pharm-e2-user-gastrointestinal17-mcq-079","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #79","q":"What is the primary gastrointestinal effect of activated charcoal?","options":["Increased gastric emptying","Stimulation of intestinal smooth muscle","Increased pancreatic enzyme secretion","Adsorption and sequestration of toxins within the gastrointestinal tract"],"answer":3,"why":"Activated charcoal binds certain toxins in the GI lumen to limit absorption if given appropriately. It does not reliably bind every toxin and can be dangerous in patients with an unprotected airway.","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":79,"originalImportedWhy":"Uploaded answer key: Adsorption and sequestration of toxins within the gastrointestinal tract","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-gastrointestinal17-mcq-080","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #80","q":"A dog with chronic bacterial-associated diarrhea is diagnosed with hypocobalaminemia. Which treatment plan is recommended in the lecture?","options":["Oral maropitant for 48 hours","A six-week course of subcutaneous cobalamin followed by reassessment of blood concentrations","Intravenous pantoprazole indefinitely","Immediate administration of ropinirole"],"answer":1,"why":"Intestinal or pancreatic disease can impair cobalamin absorption, contributing to ongoing GI dysfunction. Supplementation route and duration should be based on patient, response and follow-up testing, not a universal fixed course.","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":80,"originalImportedWhy":"Uploaded answer key: A six-week course of subcutaneous cobalamin followed by reassessment of blood concentrations","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-gastrointestinal17-mcq-081","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #81","q":"Which medication is identified for the treatment of pancreatitis in dogs?","options":["Misoprostol","Ursodeoxycholic acid","Fuzapladib (PANOQUELL-CA1)","Lactulose"],"answer":2,"why":"Uploaded answer key: Fuzapladib (PANOQUELL-CA1)","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":81,"reviewFlag":"Lecture-specific clinical, safety, approval, or prescribing claim. Preserve the source key for study; independently verify before clinical use."},{"id":"pharm-e2-user-gastrointestinal17-mcq-082","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #82","q":"What is the therapeutic mechanism of fuzapladib?","options":["Inhibition of LFA-1-mediated neutrophil migration into the pancreas","Stimulation of pancreatic enzyme secretion","Direct inhibition of gastric proton pumps","Increased pancreatic insulin release"],"answer":0,"why":"Fuzapladib inhibits LFA-1-mediated leukocyte adhesion/migration, reducing neutrophil infiltration associated with canine acute pancreatitis. It is not established as a way to guarantee prevention of future diabetes.","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":82,"originalImportedWhy":"Uploaded answer key: Inhibition of LFA-1-mediated neutrophil migration into the pancreas","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-gastrointestinal17-mcq-083","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #83","q":"Which metabolic disease is suggested in the lecture as a possible consequence of recurrent pancreatitis in dogs?","options":["Hyperthyroidism","Hypoadrenocorticism","Diabetes insipidus","Diabetes mellitus"],"answer":3,"why":"Pancreatic inflammation can injure endocrine beta cells as well as exocrine tissue. Recurrent or severe injury may therefore impair insulin production, although many pancreatitis patients do not develop diabetes.","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":83,"reviewFlag":"Lecture-specific clinical, safety, approval, or prescribing claim. Preserve the source key for study; independently verify before clinical use.","originalImportedWhy":"Uploaded answer key: Diabetes mellitus","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-gastrointestinal17-mcq-084","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #84","q":"What is the primary hepatoprotective action of S-adenosylmethionine (SAMe)?","options":["Direct inhibition of gastric acid secretion","Reduction of oxidative damage through free-radical scavenging","Stimulation of intestinal motility","Increased hepatic copper absorption"],"answer":1,"why":"SAMe contributes to glutathione synthesis and antioxidant defense in hepatocytes. It is an adjunct, not a substitute for identifying a hepatotoxin or treating liver failure.","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":84,"originalImportedWhy":"Uploaded answer key: Reduction of oxidative damage through free-radical scavenging","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-gastrointestinal17-mcq-085","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #85","q":"Which combination correctly identifies the components of Denamarin?","options":["Lactulose and rifaximin","Ursodeoxycholic acid and acetylcysteine","SAMe and milk thistle-derived silybin","D-penicillamine and zinc gluconate"],"answer":2,"why":"Uploaded answer key: SAMe and milk thistle-derived silybin","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":85,"reviewFlag":"Lecture-specific clinical, safety, approval, or prescribing claim. Preserve the source key for study; independently verify before clinical use."},{"id":"pharm-e2-user-gastrointestinal17-mcq-086","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #86","q":"Which statement correctly distinguishes D-penicillamine from zinc gluconate in copper-associated liver disease?","options":["D-penicillamine promotes urinary copper elimination, while zinc gluconate reduces intestinal copper absorption.","D-penicillamine increases copper absorption, while zinc gluconate increases hepatic copper storage.","Both drugs stimulate bile acid production exclusively.","Both drugs increase hepatic copper deposition."],"answer":0,"why":"Penicillamine chelates copper and promotes urinary elimination; zinc reduces intestinal uptake. These approaches affect different points in copper balance and require liver and medication monitoring.","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":86,"originalImportedWhy":"Uploaded answer key: D-penicillamine promotes urinary copper elimination, while zinc gluconate reduces intestinal copper absorption.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-gastrointestinal17-mcq-087","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #87","q":"Which statement best describes ursodeoxycholic acid?","options":["It directly antagonizes dopamine receptors.","It prevents all bile production.","It increases chenodeoxycholic acid concentrations.","It promotes choleresis and reduces the relative presence of harmful bile acids."],"answer":3,"why":"Ursodeoxycholic acid is a more hydrophilic bile acid that can support bile flow and shift the bile-acid pool away from more cytotoxic species. Avoid using it to delay treatment of complete biliary obstruction.","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":87,"originalImportedWhy":"Uploaded answer key: It promotes choleresis and reduces the relative presence of harmful bile acids.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-gastrointestinal17-mcq-088","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #88","q":"Which medication is identified as an adjunctive treatment for acute hepatic injury, including acetaminophen toxicosis in cats?","options":["Cisapride","Acetylcysteine","Ropinirole","Neostigmine"],"answer":1,"why":"Uploaded answer key: Acetylcysteine","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":88,"reviewFlag":"Lecture-specific clinical, safety, approval, or prescribing claim. Preserve the source key for study; independently verify before clinical use."},{"id":"pharm-e2-user-gastrointestinal17-mcq-089","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #89","q":"How does lactulose reduce ammonia absorption in patients with hepatic encephalopathy?","options":["It stimulates ammonia production in the intestines.","It increases intestinal pH, favoring ammonia absorption.","Bacterial metabolism acidifies the intestinal lumen, converting NH3 into poorly absorbed NH4⁺.","It directly increases portal blood flow."],"answer":2,"why":"Lactulose is metabolized by colonic bacteria to organic acids, lowering luminal pH and favoring ammonium (NH4+) over diffusible ammonia (NH3). It also increases nitrogen excretion through catharsis.","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":89,"originalImportedQuestion":"How does lactulose reduce ammonia absorption in patients with hepatic encephalopathy?","originalImportedAnswer":"Bacterial metabolism acidifies the intestinal lumen, converting NH3 into poorly absorbed NH4⁺.","originalImportedWhy":"Uploaded answer key: Bacterial metabolism acidifies the intestinal lumen, converting NH3 into poorly absorbed NH4⁺."},{"id":"pharm-e2-user-gastrointestinal17-mcq-090","lecture":"Lecture 17","sourceGroup":"Lecture 17 · uploaded MCQ set","topic":"Gastrointestinal & Hepatobiliary Pharmacology · #90","q":"A dog with a portosystemic shunt continues to experience hepatic encephalopathy despite lactulose therapy. Which adjunctive drug is identified in the lecture, and how does it work?","options":["Rifaximin, which reduces urease-positive intestinal bacteria and ammonia production","Fuzapladib, which inhibits LFA-1 in the liver","Omeprazole, which inhibits ammonia production by blocking proton pumps","Maropitant, which increases intestinal ammonia elimination"],"answer":0,"why":"Rifaximin reduces intestinal bacterial production of ammonia while lactulose reduces ammonia absorption. Hepatic encephalopathy also requires identifying precipitating causes, not only suppressing bacteria.","source":"User-supplied Lecture 17 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":90,"reviewFlag":"Lecture-specific clinical, safety, approval, or prescribing claim. Preserve the source key for study; independently verify before clinical use.","originalImportedWhy":"Uploaded answer key: Rifaximin, which reduces urease-positive intestinal bacteria and ammonia production","rationaleStatus":"reviewed-mechanism"}];const target=window.VPQ_PHARM_EXAM2_PDF_PRACTICE||(window.VPQ_PHARM_EXAM2_PDF_PRACTICE=[]);const ids=new Set(target.map(x=>x.id));for(const q of bank){if(!ids.has(q.id)){target.push(q);ids.add(q.id)}}window.VPQ_PHARM_GI17_UPLOADED_MCQ_COUNT=bank.length;})();
